package com.gymmind.membership.infrastructure.persistence; import com.gymmind.membership.domain.model.MemberMembership; import com.gymmind.membership.domain.repository.MemberMembershipRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Repository; @Repository class JpaMemberMembershipRepository implements MemberMembershipRepository{private final SpringDataMemberMembershipRepository d;JpaMemberMembershipRepository(SpringDataMemberMembershipRepository d){this.d=d;}public MemberMembership save(MemberMembership m){return d.save(m);}public Page<MemberMembership> findAllByTenantIdAndMemberId(Long t,Long m,Pageable p){return d.findAllByTenantIdAndMemberId(t,m,p);}}
